sksl:
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 toLayer;
uniform float3x3 fromLayer;
uniform float time;
uniform float startX;
uniform float startY;
uniform float endX;
uniform float endY;
uniform float width;
uniform float energy;
float4 readInput(float2 uv){if(uv.x<0.0||uv.y<0.0||uv.x>1.0||uv.y>1.0)return float4(0.0);return float4(image.eval(uv * size));}
half4 main(float2 coord){float2 a=float2(startX,startY),b=float2(endX,endY),p=(coord / size);float2 v=b-a;float h=clamp(dot(p-a,v)/max(dot(v,v),.00001),0.0,1.0);float d=length(p-a-v*h);float core=exp(-d*d/max(width*width,.000001)),halo=exp(-d/max(width*5.0,.0001))*.4;float g=clamp((core+halo)*energy,0.0,1.0);float4 c=readInput(p);float3 glow=mix(float3(.1,.5,1.0),float3(1.0),core)*g;return float4(glow+c.rgb*(1.0-g),g+c.a*(1.0-g));}
